import json

lower=(2,2,0,0,0,0); upper=(4,4,4,4,4,4)
degrees=list(range(4,25)); hdegrees=[1,2,3,4]

def parts_between(d):
    out=[]
    def rec(i,prev,a):
        if i==6:
            if sum(a)==d: out.append(tuple(a))
            return
        lo=lower[i]; hi=min(prev,upper[i])
        for x in range(hi,lo-1,-1):
            if sum(a)+x<=d: rec(i+1,x,a+[x])
    rec(0,4,[])
    return sorted(out,reverse=True)

def pieri(lam,mu,t):
    if sum(mu)-sum(lam)!=t: return 0
    # mu/lambda is a horizontal strip iff mu_i >= lambda_i >= mu_{i+1}
    return int(all(mu[i]>=lam[i] and lam[i]>=(mu[i+1] if i+1<6 else 0) for i in range(6)))

def eye(n): return [[int(i==j) for j in range(n)] for i in range(n)]
def cp(A): return [r[:] for r in A]
def matmul(A,B):
    return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))] if A else []
def det_bareiss(A):
    n=len(A)
    if n==0: return 1
    B=cp(A); sign=1; old=1
    for k in range(n-1):
        p=next((i for i in range(k,n) if B[i][k]),None)
        if p is None:return 0
        if p!=k:B[k],B[p]=B[p],B[k];sign=-sign
        pivot=B[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n): B[i][j]=(B[i][j]*pivot-B[i][k]*B[k][j])//old
        old=pivot
        for i in range(k+1,n): B[i][k]=0
    return sign*B[-1][-1]

def smith_witness(M):
    A=cp(M); m=len(A); n=len(A[0]) if m else 1
    U=eye(m); V=eye(n); ops=[]
    def ra(i,j,q):
        for c in range(n): A[i][c]+=q*A[j][c]
        for c in range(m): U[i][c]+=q*U[j][c]
        ops.append(['ra',i,j,q])
    def ca(i,j,q):
        for r in range(m): A[r][i]+=q*A[r][j]
        for r in range(n): V[r][i]+=q*V[r][j]
        ops.append(['ca',i,j,q])
    def rs(i,j):
        A[i],A[j]=A[j],A[i]; U[i],U[j]=U[j],U[i]; ops.append(['rs',i,j])
    def cs(i,j):
        for r in range(m): A[r][i],A[r][j]=A[r][j],A[r][i]
        for r in range(n): V[r][i],V[r][j]=V[r][j],V[r][i]
        ops.append(['cs',i,j])
    def rn(i):
        for c in range(n): A[i][c]=-A[i][c]
        for c in range(m): U[i][c]=-U[i][c]
        ops.append(['rn',i])
    k=0
    while k<m and k<n:
        pos=next(((i,j) for i in range(k,m) for j in range(k,n) if A[i][j]!=0),None)
        if pos is None: break
        if pos[0]!=k:rs(k,pos[0])
        if pos[1]!=k:cs(k,pos[1])
        while True:
            changed=True
            while changed:
                changed=False
                for i in range(k+1,m):
                    if A[i][k]:
                        q=A[i][k]//A[k][k]
                        ra(i,k,-q)
                        if A[i][k]: rs(i,k)
                        changed=True; break
                if changed: continue
                for j in range(k+1,n):
                    if A[k][j]:
                        q=A[k][j]//A[k][k]
                        ca(j,k,-q)
                        if A[k][j]: cs(j,k)
                        changed=True; break
            bad=next(((i,j) for i in range(k+1,m) for j in range(k+1,n) if A[i][j]%A[k][k]!=0),None)
            if bad is None: break
            ca(k,bad[1],1)
        if A[k][k]<0: rn(k)
        k+=1
    return A,U,V,ops

def replay(M,ops):
    A=cp(M); m=len(A); n=len(A[0]) if m else 1
    for op in ops:
        tag=op[0]
        if tag=='ra':
            _,i,j,q=op
            for c in range(n):A[i][c]+=q*A[j][c]
        elif tag=='ca':
            _,i,j,q=op
            for r in range(m):A[r][i]+=q*A[r][j]
        elif tag=='rs':
            _,i,j=op; A[i],A[j]=A[j],A[i]
        elif tag=='cs':
            _,i,j=op
            for r in range(m):A[r][i],A[r][j]=A[r][j],A[r][i]
        else:
            _,i=op
            for c in range(n):A[i][c]=-A[i][c]
    return A
records=[]
for d in degrees:
    cols=parts_between(d)
    rows=[]; labels=[]; zeros=[]
    for t in hdegrees:
        for lam in parts_between(d-t):
            r=[pieri(lam,mu,t) for mu in cols]
            rows.append(r); labels.append([t,list(lam)])
            if not any(r): zeros.append([t,list(lam)])
    M=rows
    D,U,V,ops=smith_witness(M)
    product=matmul(matmul(U,M),V) if M else []
    diagonal=all(D[i][j]==(D[i][i] if i==j else 0) for i in range(len(D)) for j in range(len(D[0]))) if D else True
    rank=sum(1 for i in range(min(len(D),len(D[0]) if D else 0)) if D[i][i]!=0)
    sd=[D[i][i] for i in range(rank)]
    checks={'shapeCompatible':len(U)==len(M) and len(V)==len(cols),'replayEqualsTracked':replay(M,ops)==D,'UMVEqualsD':product==D,'diagonal':diagonal,'smithPositivityDivisibility':all(x>0 for x in sd) and all(sd[i+1]%sd[i]==0 for i in range(len(sd)-1)),'detU':det_bareiss(U),'detV':det_bareiss(V)}
    checks['unimodularU']=abs(checks['detU'])==1; checks['unimodularV']=abs(checks['detV'])==1
    records.append({'degree':d,'orderedBasis':[list(x) for x in cols],'rowLabels':labels,'zeroRowLabels':zeros,'M':M,'matrixShape':[len(M),len(cols)],'operationLog':ops,'replay':replay(M,ops),'U':U,'V':V,'D':D,'DShape':[len(D),len(cols)],'smithDiagonal':sd,'rank':rank,'quotientFreeRank':len(cols)-rank,'torsionInvariantFactors':[x for x in sd if x>1],'checks':checks})
allok=all(all(r['checks'][x] for x in ['shapeCompatible','replayEqualsTracked','UMVEqualsD','diagonal','smithPositivityDivisibility','unimodularU','unimodularV']) for r in records)
out={'inputs':{'lower':list(lower),'upper':list(upper),'degrees':degrees,'hDegrees':hdegrees,'columnOrder':'reverse lexicographic','rowOrder':'h-degree then source reverse lexicographic','pieriRule':'coefficient 1 iff mu_i >= lambda_i >= mu_(i+1) for all i, else 0'},'records':records,'degree4Boundary':records[0],'allChecksPass':allok}
print(json.dumps(out,separators=(',',':')))
